<?php
require_once __DIR__.'/../../includes/db.php';require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/business_helpers.php';require_login();$error='';$selected=(int)($_GET['car_id']??0);$cars=$conn->query("SELECT id,car_name,plate_number FROM cars ORDER BY status='IN_STOCK' DESC,car_name");
if($_SERVER['REQUEST_METHOD']==='POST'){$car=(int)($_POST['car_id']??0);$type=trim($_POST['document_type']??'');$number=trim($_POST['document_number']??'');$status=$_POST['status']??'AVAILABLE';$expiry=$_POST['expiry_date']?:null;$notes=trim($_POST['notes']??'');if(!$car||$type===''){$error='Car and document type are required.';}else{$st=$conn->prepare('INSERT INTO car_documents(car_id,document_type,document_number,status,expiry_date,notes) VALUES(?,?,?,?,?,?)');$st->bind_param('isssss',$car,$type,$number,$status,$expiry,$notes);if($st->execute()){$docId=(int)$st->insert_id;car_sales_audit($conn,'CREATE','vehicle_document',$docId,'Added vehicle document '.$type.'.',null,['car_id'=>$car,'document_type'=>$type,'document_number'=>$number,'status'=>$status,'expiry_date'=>$expiry]);set_flash('success','Document record added.');redirect_to('backend/documents/index.php?car_id='.$car);}else{$error='Could not add document.';}}}
$page_title='Add Vehicle Document';include __DIR__.'/../includes/header.php';include __DIR__.'/../includes/leftsidebar.php';?>
<div class="content-page"><h1 class="page-title">Add Vehicle Document</h1><div class="card form-card"><?php if($error):?><div class="flash-message error" style="position:static"><?=e($error)?></div><?php endif;?><form method="post"><div class="form-group"><label>Car *</label><select name="car_id" required><option value="">Select car</option><?php while($c=$cars->fetch_assoc()):?><option value="<?=$c['id']?>" <?=$selected===$c['id']?'selected':''?>><?=e($c['car_name'].' / '.car_sales_plate_label($c['plate_number']))?></option><?php endwhile;?></select></div><div class="form-row"><div class="form-group"><label>Document Type *</label><select name="document_type"><option>Logbook / Registration Card</option><option>Import / Customs Document</option><option>Road Licence</option><option>Inspection Certificate</option><option>Insurance</option><option>Ownership Transfer</option><option>Purchase Agreement</option><option>Other</option></select></div><div class="form-group"><label>Document Number</label><input name="document_number"></div></div><div class="form-row"><div class="form-group"><label>Status</label><select name="status"><option>AVAILABLE</option><option>PENDING</option><option>MISSING</option></select></div><div class="form-group"><label>Expiry Date</label><input type="date" name="expiry_date"></div></div><div class="form-group"><label>Notes</label><textarea name="notes" rows="3"></textarea></div><button class="btn btn-green">Save Document</button><a class="btn btn-dark" href="index.php">Cancel</a></form></div></div><?php include __DIR__.'/../includes/footer.php';?>
